SQL mô hình sinh:
SELECT COUNT(*) 
FROM posts 
WHERE OwnerDisplayName = 'csgillespie' AND ParentId IS NULL;

SELECT SUM(Score) AS Total_Votes
FROM posts
WHERE Title LIKE '%data visualization%';

SELECT COUNT(*) FROM tags WHERE ExcerptPostId IN (
    SELECT Id FROM posts WHERE AnswerCount BETWEEN 5000 AND 7000
);

SELECT DISTINCT YEAR
FROM cars_data
WHERE Horsepower BETWEEN 3000 AND 4000;

SELECT SUM(e.Bonus) FROM evaluation e
JOIN hiring h ON e.Employee_ID = h.Employee_ID
JOIN shop s ON h.Shop_ID = s.Shop_ID;

SELECT CASE WHEN COUNT(*) > 0 THEN 'Có' ELSE 'Không' END AS Result
FROM cards
WHERE faceName = 'Adarkar Valkyrie' AND isOnlineOnly = 1;
